const MESSAGE_TYPES = ["text","image","document","audio","video","location","button","interactive","contacts","sticker","reaction","unsupported"];

function toE164(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const digits = raw.replace(/[^0-9]/g, '');
  if (raw.startsWith('+')) return digits ? `+${digits}` : '';
  if (digits.startsWith('593')) return `+${digits}`;
  if (digits.startsWith('0') && digits.length === 10) return `+593${digits.slice(1)}`;
  if (digits.length === 9 && digits.startsWith('9')) return `+593${digits}`;
  return digits ? `+${digits}` : '';
}

function normalizeKey(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function normalizeTimestamp(value, epochSeconds = false) {
  if (value === null || value === undefined || value === '') return null;
  const raw = String(value).trim();
  const numeric = Number(raw);
  const date = Number.isFinite(numeric)
    ? new Date(epochSeconds || numeric < 9999999999 ? numeric * 1000 : numeric)
    : new Date(raw);
  return Number.isFinite(date.getTime()) ? date.toISOString() : null;
}

function validatedWamid(value) {
  const id = String(value || '').trim();
  return /^wamid\.[A-Za-z0-9._~+\/-]+={0,2}$/.test(id) ? id : null;
}

function optionalString(value) {
  if (value === null || value === undefined || value === '') return null;
  return typeof value === 'string' ? value : JSON.stringify(value);
}

function normalizeAttachmentFileSize(value) {
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) return Math.round(numeric);
  const match = String(value || '').trim().match(/^([0-9]+(?:\.[0-9]+)?)\s*(B|KB|MB|GB)$/i);
  if (!match) return null;
  const multipliers = { B: 1, KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3 };
  const bytes = Number(match[1]) * multipliers[match[2].toUpperCase()];
  return Number.isFinite(bytes) && bytes > 0 ? Math.round(bytes) : null;
}

function firstMatchingMessage(body) {
  if (body.message && typeof body.message === 'object') return body.message;
  if (body.id && ('content' in body || 'source_id' in body || 'message_type' in body)) return body;
  const candidates = [
    ...(Array.isArray(body.conversation?.messages) ? body.conversation.messages : []),
    ...(Array.isArray(body.messages) ? body.messages : []),
  ];
  const requestedId = String(body.id || body.message_id || '').trim();
  if (requestedId) {
    const exact = candidates.find((message) => String(message?.id || '') === requestedId);
    if (exact) return exact;
  }
  return candidates.length === 1 ? candidates[0] : {};
}

function chatwootMessageCandidates(body) {
  const candidates = [
    body.message,
    body.id && ('content' in body || 'source_id' in body || 'message_type' in body) ? body : null,
    ...(Array.isArray(body.conversation?.messages) ? body.conversation.messages : []),
    ...(Array.isArray(body.messages) ? body.messages : []),
  ];
  return candidates.filter((candidate, index) => candidate && typeof candidate === 'object'
    && candidates.indexOf(candidate) === index);
}

function findMetadataWamid(message) {
  const containers = [message.content_attributes, message.additional_attributes, message.metadata];
  const keys = ['provider_message_id', 'whatsapp_message_id', 'wa_message_id', 'wamid'];
  for (const container of containers) {
    if (!container || typeof container !== 'object') continue;
    for (const key of keys) {
      const id = validatedWamid(container[key]);
      if (id) return id;
    }
    const external = validatedWamid(container.external_source_ids?.whatsapp);
    if (external) return external;
  }
  return null;
}

function normalizeChatwootWebhook(body, config = {}) {
  const conversation = body.conversation || {};
  const message = firstMatchingMessage(body);
  const inbox = body.inbox || conversation.inbox || message.inbox || {};
  const account = body.account || {};
  const sender = message.sender || body.sender || conversation.meta?.sender || body.contact || {};
  const event = String(body.event || body.name || '').trim();
  const chatwootDirection = String(body.message_type || message.message_type || '').toLowerCase();
  const nestedDirection = String(message.message_type ?? conversation.messages?.[0]?.message_type ?? '').toLowerCase();
  const senderType = String(message.sender_type || body.sender_type || sender.type || '').toLowerCase();
  const isPrivate = body.private === true || message.private === true;
  const inboxName = String(inbox.name || conversation.inbox_name || '').trim();
  const inboxId = String(inbox.id || conversation.inbox_id || body.inbox_id || '').trim();
  const payloadAccountId = String(account.id || body.account_id || conversation.account_id || '').trim();
  const accountId = payloadAccountId || String(config.accountId || '').trim();
  const conversationId = String(conversation.id || body.conversation_id || message.conversation_id || '').trim();
  const displayId = String(conversation.display_id || conversationId || '').trim();
  const chatwootMessageId = String(message.id || body.id || body.message_id || '').trim();
  const senderId = String(message.sender_id || body.sender_id || sender.id || '').trim();
  const senderName = String(sender.name || body.sender_name || '').trim();
  const attrs = message.content_attributes || body.content_attributes || {};
  const additional = message.additional_attributes || body.additional_attributes || {};
  const messageStatus = String(body.status || message.status || attrs.status || '').toLowerCase();
  const deliveryError = optionalString(attrs.external_error || attrs.error || additional.external_error || additional.error);
  const callbackTimestamp = normalizeTimestamp(body.created_at || message.created_at);
  const expectedInboxId = String(config.inboxId || '').trim();
  const expectedInboxName = String(config.inboxName || 'Agente AIGENTS RENOVACIONES 9663');
  const expectedSuffix = String(config.wabaSuffix || '9663');
  const expectedAccountId = String(config.accountId || '').trim();
  const camilaMarker = String(config.camilaMarker || 'REN-DEV-WF-03B').toLowerCase();
  const nameNorm = normalizeKey(inboxName);
  const inboxMatches =
    (expectedInboxId && inboxId === expectedInboxId)
    || (expectedInboxName && nameNorm === normalizeKey(expectedInboxName))
    || (expectedSuffix && nameNorm.includes('renovaciones') && nameNorm.includes(expectedSuffix));
  const accountMatches = !expectedAccountId || payloadAccountId === expectedAccountId;
  const isOutgoing = ['outgoing', '1'].includes(chatwootDirection)
    || ['outgoing', '1'].includes(nestedDirection);
  const generatedBy = String(attrs.generated_by || additional.generated_by || '').toLowerCase();
  const generatedActor = String(attrs.actor || additional.actor || '').toLowerCase();
  const generatedByCamila = generatedBy === camilaMarker || generatedActor === 'camila';
  const humanShapeValid = /^\d+$/.test(conversationId)
    && /^\d+$/.test(chatwootMessageId)
    && /^\d+$/.test(senderId)
    && Boolean(callbackTimestamp);
  const humanIntervention = event === 'message_created'
    && inboxMatches
    && accountMatches
    && isOutgoing
    && !isPrivate
    && senderType === 'user'
    && !generatedByCamila
    && !deliveryError
    && messageStatus !== 'failed'
    && humanShapeValid;

  if (humanIntervention) {
    return {
      route: 'human_intervention',
      source_channel: 'chatwoot_waba',
      chatwoot_account_id: accountId,
      chatwoot_inbox_id: inboxId,
      chatwoot_inbox_name: inboxName,
      chatwoot_conversation_id: conversationId,
      chatwoot_display_id: displayId,
      chatwoot_message_id: chatwootMessageId,
      chatwoot_sender_id: Number(senderId),
      chatwoot_sender_name: senderName || null,
      chatwoot_sender_type: senderType,
      chatwoot_direction: 'outgoing',
      chatwoot_private: false,
      chatwoot_message_status: messageStatus || null,
      chatwoot_delivery_error: null,
      message_text: String(optionalString(body.content || message.content || message.text?.body) || '').trim(),
      message_timestamp: callbackTimestamp,
      source_event_key: `cw-human:${conversationId}:${chatwootMessageId}`,
      raw_event: event,
    };
  }

  const isInbound = event === 'message_created' && chatwootDirection === 'incoming' && !isPrivate;
  const senderOk = !senderType || senderType === 'contact';

  if (!inboxMatches || !accountMatches || !isInbound || !senderOk) {
    return {
      route: 'ignore',
      ignore_reason: !inboxMatches
        ? 'other_inbox'
        : (!accountMatches
          ? 'other_account'
          : (isOutgoing && senderType === 'user' && !generatedByCamila
            ? 'invalid_human_intervention_event'
            : (!isInbound ? 'not_inbound_message' : 'non_contact_sender'))),
      event,
      message_type: chatwootDirection,
      sender_type: senderType,
      inbox_name: inboxName,
      inbox_id: inboxId,
    };
  }

  const phone = toE164(sender.phone_number || body.sender?.phone_number || body.contact?.phone_number || conversation.meta?.sender?.phone_number);
  const profileName = String(sender.name || body.sender?.name || body.contact?.name || conversation.meta?.sender?.name || '');
  const buttonReply = attrs.button_reply || attrs.submitted_values || message.interactive?.button_reply || message.interactive?.list_reply || {};
  const buttonPayload = optionalString(buttonReply.id || buttonReply.payload || message.button?.payload);
  const buttonText = optionalString(buttonReply.title || buttonReply.text || message.button?.text);
  const interactiveType = optionalString(
    attrs.interactive_type
    || (message.interactive?.button_reply ? 'button_reply' : null)
    || (message.interactive?.list_reply ? 'list_reply' : null),
  );
  const attachments = Array.isArray(message.attachments || body.attachments) ? (message.attachments || body.attachments) : [];
  const attachment = attachments[0] || {};
  const attachmentType = String(attachment.file_type || attachment.message_type || '').toLowerCase();
  const mimeType = optionalString(attachment.content_type && String(attachment.content_type).includes('/') ? attachment.content_type : null);
  let contractType = 'text';
  if (attrs.is_unsupported === true) contractType = 'unsupported';
  else if (buttonPayload || buttonText || interactiveType) contractType = interactiveType ? 'interactive' : 'button';
  else if (attachmentType === 'image') contractType = 'image';
  else if (attachmentType === 'audio') contractType = 'audio';
  else if (attachmentType === 'video') contractType = 'video';
  else if (attachmentType === 'file') contractType = 'document';
  else if (attachmentType === 'location') contractType = 'location';
  else if (attachmentType === 'contact') contractType = 'contacts';
  else if (attachments.length) contractType = 'unsupported';

  const providerMessageId = validatedWamid(body.source_id)
    || chatwootMessageCandidates(body)
      .filter((candidate) => !chatwootMessageId || String(candidate.id || '') === chatwootMessageId)
      .map((candidate) => validatedWamid(candidate.source_id) || findMetadataWamid(candidate))
      .find(Boolean)
    || null;
  // Chatwoot may publish the agent-bot event before source_id is committed.
  // Its own numeric tuple is the stable local identity; a later wamid only
  // enriches that event and must never turn it into a second conversational turn.
  const localMessageId = chatwootMessageId
    ? `cw:${accountId}:${conversationId}:${chatwootMessageId}`
    : (providerMessageId || `cw:${accountId}:${conversationId}:missing-id`);
  const content = optionalString(body.content || message.content || message.text?.body);
  const latitude = optionalString(attachment.coordinates?.lat ?? attachment.latitude ?? additional.latitude);
  const longitude = optionalString(attachment.coordinates?.long ?? attachment.coordinates?.lng ?? attachment.longitude ?? additional.longitude);
  const contextProviderId = validatedWamid(attrs.in_reply_to_external_id || additional.in_reply_to_external_id);
  const callbackPayload = {
    provider_message_id: providerMessageId,
    sender_phone: phone || null,
    message_type: MESSAGE_TYPES.includes(contractType) ? contractType : 'unsupported',
    timestamp: callbackTimestamp,
    body: content,
    media_id: null,
    latitude,
    longitude,
    button_text: buttonText,
    button_payload: buttonPayload,
    interactive_type: interactiveType,
    context_provider_message_id: contextProviderId,
    mime_type: mimeType,
    file_name: optionalString(attachment.file_name || attachment.filename),
  };
  const callbackEligible = Boolean(providerMessageId && phone && callbackTimestamp);
  let text = String(content || '').trim();
  let normalizedRoute = 'message';
  if (buttonPayload || buttonText) {
    normalizedRoute = 'button_reply';
    text = `button_text: ${buttonText || '-'}\nbutton_payload: ${buttonPayload || '-'}`;
  } else if (!text && attachments.length) {
    text = `[${contractType}] mensaje no textual recibido`;
  } else if (!text) {
    text = '[chatwoot] mensaje recibido';
  }

  return {
    route: 'message',
    normalized_route: normalizedRoute,
    source_channel: 'chatwoot_waba',
    phone_e164: phone,
    profile_name: profileName,
    message_id: localMessageId,
    local_message_id: localMessageId,
    provider_message_id: providerMessageId,
    chatwoot_message_id: chatwootMessageId,
    chatwoot_conversation_id: conversationId,
    chatwoot_display_id: displayId,
    chatwoot_account_id: accountId,
    chatwoot_inbox_id: inboxId,
    chatwoot_inbox_name: inboxName,
    message_type: callbackPayload.message_type,
    message_text: text,
    media_attachment_count: attachments.length,
    media_attachment_id: optionalString(attachment.id),
    media_url: optionalString(attachment.data_url || attachment.download_url),
    media_caption: content,
    media_mime_type: mimeType,
    media_file_name: optionalString(attachment.file_name || attachment.filename),
    media_file_size: normalizeAttachmentFileSize(attachment.file_size ?? attachment.fileSize ?? attachment.size),
    message_timestamp: callbackTimestamp || new Date().toISOString(),
    provider_timestamp: callbackTimestamp,
    button_payload: buttonPayload || '',
    button_text: buttonText || '',
    salesforce_inbound_payload: callbackPayload,
    salesforce_callback_eligible: callbackEligible,
    salesforce_callback_skip_reason: callbackEligible ? null : (!providerMessageId ? 'MISSING_OR_INVALID_WAMID' : (!callbackTimestamp ? 'MISSING_PROVIDER_TIMESTAMP' : 'INVALID_SENDER_PHONE')),
    raw_event: event,
  };
}

