try {
  const tokenResponse = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'client_credentials', client_id: clientId, client_secret: clientSecret })
  });
  const tokenText = await tokenResponse.text();
  let tokenBody = {};
  try { tokenBody = tokenText ? JSON.parse(tokenText) : {}; } catch (e) { tokenBody = {}; }
  if (!tokenResponse.ok || !tokenBody.access_token) {
    return done({ routing_success: false, routing_status: 'SALESFORCE_AUTH_ERROR', routing_message: 'No se pudo obtener token Salesforce DEV.', salesforce_http_status: tokenResponse.status });
  }

  const routingUrl = new URL(salesforceBaseUrl + '/services/apexrest/quicklink/v1/routing/resolve');
  routingUrl.searchParams.set('phone', phone);
  const routingResponse = await fetch(routingUrl, {
    method: 'GET',
    headers: { authorization: 'Bearer ' + tokenBody.access_token, accept: 'application/json' }
