  if (/\b(lo voy a pensar|lo pensare|lo pienso|quiero pensarlo|dejeme pensarlo|llameme|llamenme|contacteme|escribame despues|mas tarde|despues|ahora no|luego)\b/.test(text)) return 'defer';
  if (/\b(ya no (?:lo )?necesito|no necesito (?:el|este) servicio|no me interesa|no deseo renovar|no quiero renovar|no quiero el servicio|ya no uso el servicio|no gracias|prefiero no)\b/.test(text)) return 'not_needed';
  return null;
}

function readContactPreference(text) {
  if (/\b(llameme|llamenme|llamada telefonica|prefiero (?:una )?llamada|me puede llamar|comunicarse por llamada|por llamada|marcarme)\b/.test(text)) {
    return 'Llamada telefónica';
  }
  if (/\b(por correo|al correo|por email|por mail)\b/.test(text)) return 'Correo electrónico';
  if (/\b(por whatsapp|escribame|mensaje de whatsapp)\b/.test(text)) return 'WhatsApp';
  return null;
}

