    if (!originSize) {
      return { json: mediaFailure(item, 'MEDIA_DOWNLOAD_SIZE_UNAVAILABLE') };
    }
    if (originSize > limit) return { json: mediaFailure(item, 'MEDIA_DOWNLOAD_SIZE_INVALID') };
    if (item.media_declared_size && Number(item.media_declared_size) !== originSize) {
