function bytesStartWith(buffer, values) {
  if (!buffer || buffer.length < values.length) return false;
  return values.every((value, index) => buffer[index] === value);
}

function sniffMediaSignature(buffer, kind) {
  if (!Buffer.isBuffer(buffer) || !buffer.length) return null;
  const ascii = (start, end) => buffer.subarray(start, end).toString('ascii');

  if (kind === 'image') {
    if (bytesStartWith(buffer, [0xff, 0xd8, 0xff])) return 'image/jpeg';
    if (bytesStartWith(buffer, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
    if (ascii(0, 4) === 'RIFF' && ascii(8, 12) === 'WEBP') return 'image/webp';
    if (ascii(4, 8) === 'ftyp') {
      const brand = ascii(8, 12).toLowerCase();
      if (['heic', 'heix', 'hevc', 'hevx', 'heim', 'heis'].includes(brand)) return 'image/heic';
      if (['heif', 'mif1', 'msf1'].includes(brand)) return 'image/heif';
    }
    return null;
  }

  if (kind === 'audio') {
    if (ascii(0, 4) === 'OggS') return 'audio/ogg';
    if (ascii(0, 4) === 'fLaC') return 'audio/flac';
    if (ascii(0, 4) === 'RIFF' && ascii(8, 12) === 'WAVE') return 'audio/wav';
    if (ascii(0, 6) === '#!AMR\n' || ascii(0, 9) === '#!AMR-WB\n') return 'audio/amr';
    if (ascii(0, 8) === 'OpusHead') return 'audio/opus';
    if (buffer[0] === 0xff && (buffer[1] === 0xf1 || buffer[1] === 0xf9)) return 'audio/aac';
    if (ascii(0, 3) === 'ID3'
      || (buffer[0] === 0xff && (buffer[1] & 0xe0) === 0xe0 && (buffer[1] & 0x06) !== 0)) return 'audio/mpeg';
    if (bytesStartWith(buffer, [0x1a, 0x45, 0xdf, 0xa3])) return 'audio/webm';
    if (ascii(4, 8) === 'ftyp') return 'audio/mp4';
  }
  return null;
}

function parseContentRange(value) {
  const match = String(value || '').trim().match(/^bytes\s+(\d+)-(\d+)\/(\d+)$/i);
  if (!match) return null;
  return { start: Number(match[1]), end: Number(match[2]), total: Number(match[3]) };
}

function headerValue(headers, name) {
  const target = String(name || '').toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? (value.length === 1 ? value[0] : null) : value;
  }
  return null;
}

function parseContentLength(value) {
  const raw = String(value || '').trim();
  if (!/^[0-9]+$/.test(raw)) return 0;
  const size = Number(raw);
  return Number.isSafeInteger(size) && size > 0 ? size : 0;
}

function validateDownloadedMedia(item, download, maxBytes = MAX_MEDIA_BYTES[item?.media_kind]) {
  if (!item?.media_should_download || !item?.media_kind) return mediaFailure(item, 'MEDIA_DOWNLOAD_NOT_REQUESTED');
  const body = Buffer.isBuffer(download?.body)
    ? download.body
    : (download?.body instanceof Uint8Array ? Buffer.from(download.body) : null);
  if (!body || !body.length) return mediaFailure(item, 'MEDIA_DOWNLOAD_FAILED');
  if (!Number.isFinite(maxBytes) || maxBytes <= 0 || body.length > maxBytes) {
    return mediaFailure(item, 'MEDIA_DOWNLOAD_SIZE_INVALID');
  }

  const expectedSize = Number(item.media_head_content_length || 0);
  if (!Number.isSafeInteger(expectedSize) || expectedSize <= 0 || body.length !== expectedSize) {
    return mediaFailure(item, 'MEDIA_DOWNLOAD_SIZE_MISMATCH');
  }

  const status = Number(download.statusCode || 0);
  const contentRange = parseContentRange(headerValue(download.headers, 'content-range'));
  if (status && ![200, 206].includes(status)) {
    return mediaFailure(item, 'MEDIA_DOWNLOAD_HTTP_INVALID');
  }
  if (status === 206 && !contentRange) return mediaFailure(item, 'MEDIA_DOWNLOAD_RANGE_INVALID');
  if (contentRange && (contentRange.start !== 0 || contentRange.end + 1 !== body.length
    || contentRange.total !== expectedSize || contentRange.total > maxBytes)) {
    return mediaFailure(item, contentRange.total > maxBytes ? 'MEDIA_DOWNLOAD_SIZE_INVALID' : 'MEDIA_DOWNLOAD_RANGE_INVALID');
  }

  const rawContentLength = headerValue(download.headers, 'content-length');
  if (rawContentLength !== null && rawContentLength !== undefined) {
    const responseLength = parseContentLength(rawContentLength);
    if (!responseLength || responseLength !== body.length) {
      return mediaFailure(item, 'MEDIA_DOWNLOAD_SIZE_MISMATCH');
    }
  }

  const sniffedMime = sniffMediaSignature(body, item.media_kind);
  if (!sniffedMime) return mediaFailure(item, 'MEDIA_DOWNLOAD_SIGNATURE_INVALID');
  const allowedMimes = item.media_kind === 'audio' ? AUDIO_MIMES : IMAGE_MIMES;
  if (!allowedMimes.has(sniffedMime)) return mediaFailure(item, 'MEDIA_DOWNLOAD_MIME_INVALID');
  return {
    ...item,
    media_download_valid: true,
    media_download_size: body.length,
    media_download_mime_type: sniffedMime,
    media_download_response_mime_type: cleanText(headerValue(download.headers, 'content-type'), 100) || null,
    media_download_body: body,
  };
}

function safeFileName(value, kind, mime) {
  const cleaned = String(value || '').replace(/[\\/"\u0000-\u001f\u007f]/g, '_').trim().slice(0, 180);
  const extensions = {
    'audio/flac': 'flac', 'audio/mp4': 'm4a', 'audio/mpeg': 'mp3', 'audio/ogg': 'ogg', 'audio/wav': 'wav',
    'audio/webm': 'webm', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp',
  };
  const extension = extensions[mime] || 'bin';
  const stem = cleaned.replace(/\.[^.]*$/, '').slice(0, 175) || `inbound-${kind}`;
  return `${stem}.${extension}`;
}

