function inspectCamilaLlmResponse(response, provider, startedAtMs) {
  const providerName = provider === 'gemini' ? 'gemini' : 'openai';
  const rawStatus = Number(response?.statusCode ?? response?.status ?? 0);
  const status = Number.isInteger(rawStatus) && rawStatus >= 100 && rawStatus <= 599 ? rawStatus : 0;
  const started = Number(startedAtMs);
  const elapsed = Date.now() - started;
  const latencyMs = Number.isFinite(started) && started > 0 && Number.isFinite(elapsed) && elapsed >= 0 && elapsed <= 120000
    ? Math.round(elapsed)
    : null;
  function failure(reason) {
    return {
      valid: false,
      candidate: null,
      attempt: { provider: providerName, http_status: status, failure_reason: reason, latency_ms: latencyMs },
    };
  }
  if (!(status >= 200 && status < 300)) return failure(`llm_http_${status}`);

  const body = response?.body ?? {};
  const content = body?.choices?.[0]?.message?.content;
  if (typeof content !== 'string' || !content.trim()) return failure('llm_output_not_json');
  let parsed;
  try { parsed = JSON.parse(content); } catch (error) { return failure('llm_output_not_json'); }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return failure('llm_output_not_json');

  const allowedActions = ['reply', 'handoff', 'close_not_interested', 'payment'];
  if (!allowedActions.includes(parsed.action)) return failure('invalid_llm_action');
  if (typeof parsed.message !== 'string') return failure('llm_invalid_message_type');
  const message = parsed.message.trim();
  if (!message) return failure('llm_empty_message');
  const metadata = parsed.metadata && typeof parsed.metadata === 'object' && !Array.isArray(parsed.metadata)
    ? { ...parsed.metadata }
    : {};
  return {
    valid: true,
    candidate: { action: parsed.action, message, metadata },
    attempt: { provider: providerName, http_status: status, failure_reason: null, latency_ms: latencyMs },
  };
}

